OPJ_BOOL write_j2k_first_tile_part(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_BYTE *data = p_data;
    OPJ_UINT32 data_left = p_total_data_size;
    OPJ_BOOL result = OPJ_TRUE;

    /* Write SOT marker */
    if (data_left < 6) {
        result = OPJ_FALSE;
        opj_event_msg(p_manager, EVT_ERROR, "Not enough space to write SOT marker.\n");
        goto cleanup;
    }
    data[0] = 0xff;
    data[1] = 0x90;
    OPJ_UINT16 sot_length = 6 + (OPJ_UINT16)(4 * p_j2k->numresolution);
    OPJ_UINT16_to_OCTETSTRING(sot_length, data + 2);
    data[4] = (OPJ_BYTE)(p_j2k->current_tile_number >> 8);
    data[5] = (OPJ_BYTE)(p_j2k->current_tile_number & 0xFF);
    data += 6;
    data_left -= 6;

    /* Write tile component information if applicable */
    if (p_j2k->csty & J2K_CSTY_CPRECINCTS) {
        OPJ_UINT32 i;
        for (i = 0; i < p_j2k->numresolution; ++i) {
            if (data_left < 2) {
                result = OPJ_FALSE;
                opj_event_msg(p_manager, EVT_ERROR, "Not enough space to write tile component information.\n");
                goto cleanup;
            }
            data[0] = (OPJ_BYTE)(p_j2k->resolutions[i].x0 >> 8);
            data[1] = (OPJ_BYTE)(p_j2k->resolutions[i].x0 & 0xFF);
            data += 2;
            data_left -= 2;
        }
    }

    /* Write SOD marker */
    if (data_left < 1) {
        result = OPJ_FALSE;
        opj_event_msg(p_manager, EVT_ERROR, "Not enough space to write SOD marker.\n");
        goto cleanup;
    }
    data[0] = 0xff;
    data[1] = 0x91;
    data += 1;
    data_left -= 1;

    *p_data_written = (OPJ_UINT32)(data - p_data);

cleanup:
    return result;
}

OPJ_BOOL write_first_tile_part(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                               OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                               struct opj_event_mgr *p_manager) {
    if (!p_j2k || !p_data || !p_data_written || !p_stream || !p_manager) {
        return OPJ_FALSE;
    }

    OPJ_UINT32 bytes_written = 0;

    /* Write SOT marker (Start of Tile) */
    if (bytes_written + 6 > p_total_data_size) {
        return OPJ_FALSE;
    }
    OPJ_UINT32 sot_length = 4 + 2 + 2; /* Length (4), Tile Part Index (2), Tile Part Length (2) */
    OPJ_UINT16 tile_part_index = 0;
    OPJ_UINT16 tile_part_length = 0;

    memcpy(p_data + bytes_written, "\xFF\x91", 2); /* SOT marker */
    bytes_written += 2;
    memcpy(p_data + bytes_written, &sot_length, 4);
    bytes_written += 4;
    memcpy(p_data + bytes_written, &tile_part_index, 2);
    bytes_written += 2;
    memcpy(p_data + bytes_written, &tile_part_length, 2);
    bytes_written += 2;

    /* Write TCM (Tile Component) marker if required */
    if (p_j2k->cinema && p_j2k->cinema->tccp) {
        if (bytes_written + 2 > p_total_data_size) {
            return OPJ_FALSE;
        }
        memcpy(p_data + bytes_written, "\xFF\x93", 2); /* TCM marker */
        bytes_written += 2;
    }

    /* Write SOD marker (Start of Data) */
    if (bytes_written + 2 > p_total_data_size) {
        return OPJ_FALSE;
    }
    memcpy(p_data + bytes_written, "\xFF\x92", 2); /* SOD marker */
    bytes_written += 2;

    *p_data_written = bytes_written;

    return OPJ_TRUE;
}

OPJ_BOOL write_j2k_tile_part(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                             OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                             struct opj_event_mgr *p_manager) {
    OPJ_UINT32 written = 0;
    OPJ_BOOL result = OPJ_TRUE;

    /* Write SOT marker */
    if (written + 10 > p_total_data_size) {
        result = OPJ_FALSE;
        opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Not enough space for SOT marker\n");
        goto cleanup;
    }
    p_data[0] = 0xFF;
    p_data[1] = 0x90;
    p_data[2] = (p_j2k->current_tile_number >> 8) & 0xFF;
    p_data[3] = p_j2k->current_tile_number & 0xFF;
    p_data[4] = (p_j2k->num_components >> 8) & 0xFF;
    p_data[5] = p_j2k->num_components & 0xFF;
    p_data[6] = (p_j2k->current_tile_data_size >> 24) & 0xFF;
    p_data[7] = (p_j2k->current_tile_data_size >> 16) & 0xFF;
    p_data[8] = (p_j2k->current_tile_data_size >> 8) & 0xFF;
    p_data[9] = p_j2k->current_tile_data_size & 0xFF;
    written += 10;
    p_data += 10;

    /* Conditionally write tile component information */
    if (p_j2k->cinema_mode) {
        if (written + 4 * p_j2k->num_components > p_total_data_size) {
            result = OPJ_FALSE;
            opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Not enough space for tile component info\n");
            goto cleanup;
        }
        for (OPJ_UINT32 i = 0; i < p_j2k->num_components; ++i) {
            p_data[0] = (p_j2k->tile_component_info[i].x0 >> 8) & 0xFF;
            p_data[1] = p_j2k->tile_component_info[i].x0 & 0xFF;
            p_data[2] = (p_j2k->tile_component_info[i].y0 >> 8) & 0xFF;
            p_data[3] = p_j2k->tile_component_info[i].y0 & 0xFF;
            p_data += 4;
            written += 4;
        }
    }

    /* Write SOD marker */
    if (written + 1 > p_total_data_size) {
        result = OPJ_FALSE;
        opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Not enough space for SOD marker\n");
        goto cleanup;
    }
    p_data[0] = 0xFF;
    p_data[1] = 0x91;
    p_data += 1;
    written += 1;

    *p_data_written = written;

cleanup:
    return result;
}

OPJ_BOOL write_j2k_first_tile_part(opj_j2k_t *p_j2k, OPJ_BYTE *p_data,
                                   OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size,
                                   opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_UINT32 written = 0;

    if (!opj_j2k_write_sot(p_j2k, p_data + written, p_total_data_size - written, p_stream, p_manager)) {
        return OPJ_FALSE;
    }
    written += 10; // SOT marker + length + tile number + tile_part number + TLX + TLY

    if (p_j2k->cinfo->cinema) {
        if (!opj_j2k_write_tco(p_j2k, p_data + written, p_total_data_size - written, p_stream, p_manager)) {
            return OPJ_FALSE;
        }
        written += 2; // TCO marker
    }

    if (!opj_j2k_write_sod(p_j2k, p_data + written, p_total_data_size - written, p_stream, p_manager)) {
        return OPJ_FALSE;
    }
    written += 1;

    *p_data_written = written;
    return OPJ_TRUE;
}
